import{_ as a,o as r,c as t,a9 as o}from"./chunks/framework.asyjyako.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture-roadmap.md","filePath":"architecture-roadmap.md","lastUpdated":null}'),n={name:"architecture-roadmap.md"};function s(i,e,l,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="Architecture" tabindex="-1">Architecture <a class="header-anchor" href="#Architecture" aria-label="Permalink to &quot;Architecture {#Architecture}&quot;">​</a></h1><p>PerfChecker keeps experiment control, measured code and presentation separate. A Julia call, VS Code command, Web job or Pluto notebook prepares the same suite plan. The controller selects targets and collectors; isolated workers execute them; interfaces read the saved result.</p><h2 id="Controller-and-workers" tabindex="-1">Controller and workers <a class="header-anchor" href="#Controller-and-workers" aria-label="Permalink to &quot;Controller and workers {#Controller-and-workers}&quot;">​</a></h2><p>Core owns discovery, plans, worker setup, measurement definitions, comparisons and reports. A plan names a package version or immutable source revision, a workload, its collector and its environment. Constructing or filtering a plan starts no measurement.</p><p><a href="https://github.com/JuliaPluto/Malt.jl" target="_blank" rel="noreferrer">Malt</a> supplies isolated Julia workers for checks. Target dependencies resolve in their worker project rather than in the editor or plotting environment. A worker&#39;s Julia version, source, dependency manifests and thread settings stay attached to its result. Remote execution also needs an explicit controller and worker lifecycle; see <a href="./tools/scenarios">Scenarios</a>.</p><h2 id="Prepare,-operate,-verify" tabindex="-1">Prepare, operate, verify <a class="header-anchor" href="#Prepare,-operate,-verify" aria-label="Permalink to &quot;Prepare, operate, verify {#Prepare,-operate,-verify}&quot;">​</a></h2><p>A feature describes three steps:</p><ol><li><p><strong>Prepare</strong> creates the input and any state excluded from measurement.</p></li><li><p><strong>Operate</strong> performs the one operation the collector observes.</p></li><li><p><strong>Verify</strong> checks the answer against an independent oracle, outside measurement.</p></li></ol><p>Fresh-state features prepare each evaluation independently. Reused state must be declared deliberately, for example for a continuous sampling profile of a read-only operation. An existing test item instead measures its whole item, including setup and assertions. Those are different measurement boundaries.</p><h2 id="Saved-bundles-and-comparisons" tabindex="-1">Saved bundles and comparisons <a class="header-anchor" href="#Saved-bundles-and-comparisons" aria-label="Permalink to &quot;Saved bundles and comparisons {#Saved-bundles-and-comparisons}&quot;">​</a></h2><p>A run bundle contains observations, measurement definitions, source/environment provenance, diagnostics and artifacts. A completed collector, a passing oracle and a passing regression budget are separate outcomes. Comparisons require compatible definitions and conditions; a zero or unavailable reference cannot acquire a meaningful percentage by plotting it.</p><p>Interfaces exchange these files instead of sharing mutable controller state. Replaying a bundle or rendering its JSON runs no workload. <a href="./tools/results">Saved results</a> explains inspection and export.</p><h2 id="Optional-tools-and-interfaces" tabindex="-1">Optional tools and interfaces <a class="header-anchor" href="#Optional-tools-and-interfaces" aria-label="Permalink to &quot;Optional tools and interfaces {#Optional-tools-and-interfaces}&quot;">​</a></h2><p>Core has no required plotting, Web or notebook application. <code>PerfCheckerMakie</code>, <code>PerfCheckerWeb</code>, <code>PerfCheckerPluto</code> and <code>PerfCheckerTachikoma</code> own their interfaces and dependencies. The VS Code client calls a Julia controller. Each companion has its own package identity and compatibility bounds.</p><p>Small integrations such as BenchmarkTools, Chairmarks, TestItemRunner, UnicodePlots and Documenter use Julia extensions. Diagnostic adapters load tools such as JET or Aqua in prepared target environments. Hardware-counter companions require their own workers and native prerequisites. Missing tools produce explicit unavailable evidence; importing Core does not certify a native backend.</p><p>See the <a href="./reference/public-api">Public API</a> for supported entry points and <a href="./contributing/">Contributing</a> for changing this code or its examples.</p>',16)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
